function canonical(value){if(value===null||typeof value!=='object')return JSON.stringify(value);if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';return '{'+Object.keys(value).filter(k=>value[k]!==undefined).sort().map(k=>JSON.stringify(k)+':'+canonical(value[k])).join(',')+'}';}
function sha(value){return 'sha256:'+createHash('sha256').update(canonical(value)).digest('hex');}
function requireCondition(value,message){if(!value)throw Error(message);}
async function fixture(role,{listDelay=0,archiveDelay=0}={}){const context=await browser.newContext({viewport:{width:1280,height:900}}),page=await context.newPage(),calls=[],errors=[],account=`00000000-0000-4000-8000-00000000000${role==='owner'?1:role==='editor'?2:3}`;await context.tracing.start({screenshots:true,snapshots:true,sources:true});page.on('pageerror',e=>errors.push(e.message));await page.route(`${endpoint}/**`,async route=>{const req=route.request(),u=new URL(req.url()),headers={'Access-Control-Allow-Origin':'*','Content-Type':'application/json'};if(req.method()==='OPTIONS'){await route.fulfill({status:204,headers:{...headers,'Access-Control-Allow-Headers':'*','Access-Control-Allow-Methods':'*'},body:''});return;}if(u.pathname==='/auth/v1/token'){calls.push({type:'auth-fixture',role});await route.fulfill({headers,body:JSON.stringify({access_token:'independent-fixture-token',user:{id:account},expires_in:3600})});return;}if(u.pathname==='/rest/v1/scenario_snapshots'){calls.push({type:'public-list'});if(listDelay)await new Promise(r=>setTimeout(r,listDelay));await route.fulfill({headers,body:JSON.stringify([{id:shared.id,content_hash:shared.contentHash,created_at:shared.createdAt,expires_at:shared.accessExpiresAt}])});return;}if(u.pathname==='/rest/v1/scenario_comments'){calls.push({type:'comments',method:req.method(),body:req.postData()});await route.fulfill({headers,body:'[]'});return;}if(u.pathname==='/functions/v1/scenario-sync'){const wire=req.postDataJSON();calls.push({type:'edge',action:wire.action,input:wire.input});let data;if(wire.action==='projects')data=role==='owner'?[{projectId:remote.project.projectId,name:remote.project.name,serverRevision:'1',role:'owner'}]:role==='editor'?[{projectId:editorImage.projectId,name:null,serverRevision:'1',role:'editor'}]:[];else if(wire.action==='shared_snapshot')data=shared;else if(wire.action==='team_read')data={...editorImage,authorizationRevision:'1',authorizationExpiresAt:null};else if(wire.action==='pull')data=remote;else if(wire.action==='apply'){const op=wire.input,map=new Map(editorImage.documents.map(d=>[d.id,structuredClone(d)]));for(const t of op.targets)map.set(t.targetId,{...structuredClone(t.local),revision:'2'});const docs=[...map.values()];data={schemaVersion:1,operationId:op.operationId,scope:op.scope,operationHash:sha(op),status:'applied',serverRevision:'2',authorizationRevision:'1',authorizationExpiresAt:null,documents:op.targets.map(t=>map.get(t.targetId)),confirmedDocuments:docs,conflicts:[]};}else if(wire.action==='download_archive'){if(archiveDelay)await new Promise(r=>setTimeout(r,archiveDelay));await route.fulfill({status:200,headers:{'Access-Control-Allow-Origin':'*','Content-Type':'application/octet-stream','Content-Length':String(archive.length)},body:archive});return;}else{await route.fulfill({status:500,headers,body:JSON.stringify({code:'UNEXPECTED_FIXTURE_ACTION',action:wire.action})});return;}await route.fulfill({headers,body:JSON.stringify(data)});return;}await route.fulfill({status:404,headers,body:'{}'});});return {context,page,calls,errors,account};}
async function login(f,query=''){await f.page.goto(url+query);await f.page.getByRole('button',{name:'アカウント・専用同期',exact:true}).click();await f.page.getByLabel('専用Supabase URL',{exact:true}).fill(endpoint+'/');await f.page.getByLabel('公開用APIキー',{exact:true}).fill('sb_publishable_independent_fixture_only');await f.page.getByRole('button',{name:'接続設定を保持',exact:true}).click();await f.page.getByLabel('メール',{exact:true}).fill('independent@example.invalid');await f.page.getByLabel('パスワード',{exact:true}).fill('fixture-not-real-password');await f.page.getByRole('button',{name:'認証してアカウント領域を開く',exact:true}).click();await f.page.getByRole('button',{name:'限定版の閲覧・指摘',exact:true}).waitFor();await f.page.getByRole('button',{name:'認証してアカウント領域を開く',exact:true}).waitFor({state:'visible'});}
async function run(id,fn){if(id==='R9USC03')return;const f=await fixture(id.startsWith('R9UE')?'editor':id.startsWith('R9UR')?'owner':'reviewer',{listDelay:id==='R9US01'?400:0,archiveDelay:id==='R9UR02'?1200:0});let status='pass',failure='',observation={};try{observation=await fn(f)||{};}catch(e){status='fail';failure=e.stack||String(e);}await f.page.screenshot({path:`${art}/${id}.png`,fullPage:true});writeFileSync(`${art}/${id}-body.txt`,await f.page.locator('body').innerText());await f.context.tracing.stop({path:`${art}/${id}.zip`});const result={id,status,expected:'Correct behavior, not observed-bad success',failure,observation,calls:f.calls,pageErrors:f.errors,environment:'Production Chromium153 at isolated5398, HTTPS backend mocks'};writeFileSync(`${art}/${id}.json`,JSON.stringify(result,null,2)+'\n');results.push(result);console.log(JSON.stringify({id,status,failure:failure.split('\n')[0],observation,calls:f.calls.map(c=>c.action??c.type),pageErrors:f.errors}));await f.context.close();}

async function accountRows(f,names){return f.page.evaluate(async ({account,names})=>{const db=await new Promise((resolve,reject)=>{const q=indexedDB.open('scenario-manager-account-'+account);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});try{const out={};for(const name of names)out[name]=await new Promise((resolve,reject)=>{const q=db.transaction(name,'readonly').objectStore(name).getAll();q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});return out;}finally{db.close();}},{account:f.account,names});}
